    // C# program to find the K-th
// largest sum of subarray

using System;
using System.Collections.Generic;
class GfG{

    // function to calculate Kth largest
    // element in contiguous subarray sum
    static int kthLargest(int[] arr, int N, int K){

        // array to store prefix sums
        int[] sum = new int[N + 1];
        sum[0] = 0;
        sum[1] = arr[0];
        for (int i = 2; i <= N; i++)
            sum[i] = sum[i - 1] + arr[i - 1];

        // priority_queue of min heap
        List<int> Q = new List<int>();

        // loop to calculate the contiguous subarray
        // sum position-wise
        for (int i = 1; i <= N; i++) {

            // loop to traverse all positions that
            // form contiguous subarray
            for (int j = i; j <= N; j++) {
                // calculates the contiguous subarray
                // sum from j to i index
                int x = sum[j] - sum[i - 1];

                // if queue has less than k elements,
                // then simply push it
                if (Q.Count < K)
                    Q.Add(x);

                else {
                    // it the min heap has equal to
                    // k elements then just check
                    // if the largest kth element is
                    // smaller than x then insert
                    // else its of no use
                    Q.Sort();
                    if (Q[0] < x) {
                        Q.RemoveAt(0);
                        Q.Add(x);
                    }
                }
                Q.Sort();
            }
        }

        // the top element will be then Kth
        // largest element
        return Q[0];
    }

    // Driver's Code
    public static void Main(String[] args)
    {
        int[] a = new int[] { 20, -5, -1 };
        int N = a.Length;
        int K = 3;

        // Function call
        Console.WriteLine(kthLargest(a, N, K));
    }
}

