    // Custom MinHeap class to act as a priority queue
class MinHeap {
    constructor() {
        this.heap = [];
    }

    // Return the top (minimum) element
    peek() {
        return this.heap[0];
    }

    // Insert a new value into the heap
    insert(val) {
        this.heap.push(val);
        this._heapifyUp(this.heap.length - 1);
    }

    // Remove and return the top (minimum) element
    extractMin() {
        if (this.heap.length === 0) return null;
        if (this.heap.length === 1) return this.heap.pop();

        const min = this.heap[0];
        this.heap[0] = this.heap.pop();
        this._heapifyDown(0);
        return min;
    }

    size() {
        return this.heap.length;
    }

    // Helper to maintain heap property after insertion
    _heapifyUp(index) {
        while (index > 0) {
            const parent = Math.floor((index - 1) / 2);
            if (this.heap[parent] > this.heap[index]) {
                [this.heap[parent], this.heap[index]] = [this.heap[index], this.heap[parent]];
                index = parent;
            } else {
                break;
            }
        }
    }

    // Helper to maintain heap property after removal
    _heapifyDown(index) {
        const n = this.heap.length;
        while (true) {
            let smallest = index;
            const left = 2 * index + 1;
            const right = 2 * index + 2;

            if (left < n && this.heap[left] < this.heap[smallest]) {
                smallest = left;
            }

            if (right < n && this.heap[right] < this.heap[smallest]) {
                smallest = right;
            }

            if (smallest !== index) {
                [this.heap[index], this.heap[smallest]] = [this.heap[smallest], this.heap[index]];
                index = smallest;
            } else {
                break;
            }
        }
    }
}

// Function to find the Kth largest subarray sum
function kthLargest(arr, k) {
    const n = arr.length;

    // Create prefix sum array
    const prefix = new Array(n + 1).fill(0);
    for (let i = 1; i <= n; i++) {
        prefix[i] = prefix[i - 1] + arr[i - 1];
    }

    // Use MinHeap to keep track of top K largest sums
    const pq = new MinHeap();

    for (let i = 1; i <= n; i++) {
        for (let j = i; j <= n; j++) {
            const sum = prefix[j] - prefix[i - 1];

            if (pq.size() < k) {
                pq.insert(sum);
            } else if (pq.peek() < sum) {
                pq.extractMin();
                pq.insert(sum);
            }
        }
    }

    return pq.peek();
}

